// Bundled card designs (public/cards/**), generated by scripts/build-card-catalog.mjs.
import catalog from './cardCatalog.json';

export interface CardDesign {
    id: string;
    bank: string;
    name: string;
    network: '' | 'visa' | 'mastercard' | 'jcb' | 'amex' | 'napas';
    type: 'credit' | 'debit';
    src: string;
    w: number;
    h: number;
}

const BANKS = catalog.banks as Record<string, { name: string; aliases: string[] }>;
const CARDS = catalog.cards as CardDesign[];

const norm = (s?: string) => (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().replace(/[^A-Z0-9]/g, '');

// Every spelling → canonical id. bankShortName in the DB is a mix of VietQR
// shortNames ("VPBank", "VietinBank") and codes ("VPB", "CTG").
const LOOKUP = new Map<string, string>();
for (const [id, b] of Object.entries(BANKS)) {
    LOOKUP.set(norm(id), id);
    LOOKUP.set(norm(b.name), id);
    b.aliases.forEach(a => LOOKUP.set(norm(a), id));
}

export function bankIdOf(bankShortName?: string, bankName?: string): string | null {
    const hit = LOOKUP.get(norm(bankShortName)) || LOOKUP.get(norm(bankName));
    if (hit) return hit;
    // "VIB Super Card" → VIB, "Thẻ Techcombank Visa" → Techcombank
    const words = (bankName || '').split(/\s+/).map(norm).filter(Boolean);
    for (const w of words) { const id = LOOKUP.get(w); if (id) return id; }
    return null;
}

/** Designs for a bank — the requested card type first, then the rest. */
export function designsFor(bankShortName?: string, bankName?: string, type?: string): CardDesign[] {
    const id = bankIdOf(bankShortName, bankName);
    if (!id) return [];
    const list = CARDS.filter(c => c.bank === id);
    if (type !== 'credit' && type !== 'debit') return list;
    return [...list.filter(c => c.type === type), ...list.filter(c => c.type !== type)];
}

export const designById = (src?: string) => CARDS.find(c => c.src === src) || null;
export const DESIGN_COUNT = CARDS.length;
